<template>
    <component v-if="!asChild" :is="as" :class="cx('root')" :type="as === 'BUTTON' ? 'button' : undefined" :disabled="disabled || undefined" data-action="zoom-in" @click="onClick" v-bind="ptmi('root')">
        <slot />
    </component>
    <slot v-else :class="cx('root')" :onClick="onClick" :disabled="disabled" />
</template>

<script>
import BaseGalleryZoomIn from './BaseGalleryZoomIn.vue';

export default {
    name: 'GalleryZoomIn',
    extends: BaseGalleryZoomIn,
    inheritAttrs: false,
    inject: ['$pcGallery'],
    methods: {
        onClick() {
            if (this.disabled) return;

            this.$pcGallery?.onClickAction('zoomIn');
        }
    },
    computed: {
        disabled() {
            return this.zoomed || !this.zoomable;
        },
        zoomable() {
            return this.$pcGallery?.activeItemTransform?.zoomable ?? true;
        },
        zoomed() {
            return this.$pcGallery?.activeItemTransform?.zoomed ?? false;
        }
    }
};
</script>
